create table if not exists public.admins(user_id uuid primary key references auth.users(id) on delete cascade);
create table if not exists public.settings(id int primary key default 1 check(id=1),site_name text not null default 'Nigerian Film Critics',tagline text not null default 'The voice of Nigerian cinema',intro text not null default 'Independent reviews, criticism and conversations about Nigerian film.');
create table if not exists public.critics(id bigint generated by default as identity primary key,name text not null,bio text default '',avatar_url text default '');
create table if not exists public.films(id bigint generated by default as identity primary key,title text not null,year int,genre text,category text default 'Nollywood',director text default '',poster_url text default '',critic_id bigint references public.critics(id) on delete set null,score numeric(3,1),summary text default '',review text default '',published boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
insert into public.settings(id) values(1) on conflict(id) do nothing;
alter table public.admins enable row level security; alter table public.settings enable row level security; alter table public.critics enable row level security; alter table public.films enable row level security;
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.admins where user_id=auth.uid()); $$;
drop policy if exists "public settings read" on public.settings; create policy "public settings read" on public.settings for select using(true);
drop policy if exists "public critics read" on public.critics; create policy "public critics read" on public.critics for select using(true);
drop policy if exists "public films read" on public.films; create policy "public films read" on public.films for select using(published=true or public.is_admin());
drop policy if exists "admin settings write" on public.settings; create policy "admin settings write" on public.settings for all using(public.is_admin()) with check(public.is_admin());
drop policy if exists "admin critics write" on public.critics; create policy "admin critics write" on public.critics for all using(public.is_admin()) with check(public.is_admin());
drop policy if exists "admin films write" on public.films; create policy "admin films write" on public.films for all using(public.is_admin()) with check(public.is_admin());
drop policy if exists "admin self read" on public.admins; create policy "admin self read" on public.admins for select using(user_id=auth.uid());